CREATE OR REPLACE FUNCTION safebus_private.shared_route_stop_geometry(p_tenant_id uuid, p_route_id uuid, p_pattern_id uuid, p_stops jsonb, p_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'extensions', 'pg_temp'
AS $function$
declare
  v_digest text := encode(sha256(convert_to(jsonb_build_array(
    p_tenant_id, p_route_id, p_pattern_id, p_stops, p_path
  )::text, 'UTF8')), 'hex');
  v_result jsonb;
  v_cache_write boolean := false;
begin
  select c.geometry_data into v_result
  from safebus_private.route_stop_geometry_cache c
  where c.route_trip_pattern_id = p_pattern_id and c.tenant_id = p_tenant_id
    and c.route_id = p_route_id and c.input_digest = v_digest;
  if found then return v_result; end if;

  -- Never wait behind another reader's cache fill. Contention or a read-only
  -- transaction computes its own exact result without modifying the cache.
  if current_setting('transaction_read_only') = 'off' then
    v_cache_write := pg_try_advisory_xact_lock(hashtextextended(
      'safebus:route-geometry:' || p_pattern_id::text, 0));
  end if;
  if v_cache_write then
    select c.geometry_data into v_result
    from safebus_private.route_stop_geometry_cache c
    where c.route_trip_pattern_id = p_pattern_id and c.tenant_id = p_tenant_id
      and c.route_id = p_route_id and c.input_digest = v_digest;
    if found then return v_result; end if;
  end if;

  with stops as (
    select s.*,
      case when s.latitude is not null and s.longitude is not null then
        extensions.st_setsrid(extensions.st_makepoint(s.longitude, s.latitude), 4326)
      end as stop_point
    from jsonb_to_recordset(p_stops) as s(
      id uuid, display_index integer, latitude double precision,
      longitude double precision, planned_arrival_time time
    )
  ), located as (
    select s.*,
      case when p_path is not null and s.stop_point is not null then
        extensions.st_linelocatepoint(p_path::extensions.geometry, s.stop_point)
      end as shape_fraction
    from stops s
  ), segments as (
    select s.*,
      lead(s.stop_point) over (order by s.display_index) as next_stop_point,
      lead(s.shape_fraction) over (order by s.display_index) as next_shape_fraction,
      lead(s.planned_arrival_time) over (order by s.display_index) as next_planned_arrival_time
    from located s
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', s.id,
    'shape_fraction', s.shape_fraction,
    'distance_m', case
      when p_path is not null and s.shape_fraction is not null
        and s.next_shape_fraction is not null and s.shape_fraction <> s.next_shape_fraction then
        extensions.st_length(extensions.st_linesubstring(p_path::extensions.geometry,
          least(s.shape_fraction, s.next_shape_fraction),
          greatest(s.shape_fraction, s.next_shape_fraction))::extensions.geography)
      when s.stop_point is not null and s.next_stop_point is not null then
        extensions.st_distance(s.stop_point::extensions.geography, s.next_stop_point::extensions.geography)
    end,
    'scheduled_seconds', case
      when s.planned_arrival_time is null or s.next_planned_arrival_time is null then null
      else mod(extract(epoch from (s.next_planned_arrival_time - s.planned_arrival_time))::integer + 86400, 86400)
    end
  ) order by s.display_index), '[]'::jsonb) into v_result from segments s;

  if v_cache_write then
    insert into safebus_private.route_stop_geometry_cache(
      route_trip_pattern_id, tenant_id, route_id, input_digest, geometry_data
    ) values (p_pattern_id, p_tenant_id, p_route_id, v_digest, v_result)
    on conflict (route_trip_pattern_id) do update set
      tenant_id = excluded.tenant_id, route_id = excluded.route_id,
      input_digest = excluded.input_digest, geometry_data = excluded.geometry_data;
  end if;
  return v_result;
end;
$function$
